"""Constructor-based circle packing for n=26: LP L-BFGS + collapse guard."""
import numpy as np
from scipy.optimize import linprog, minimize


def _pair_indices(n):
    ii, jj = [], []
    for i in range(n):
        for j in range(i + 1, n):
            ii.append(i)
            jj.append(j)
    return np.array(ii), np.array(jj)


def _solve_radii_lp(centers):
    n = len(centers)
    ii, jj = _pair_indices(n)
    d = np.hypot(centers[ii, 0] - centers[jj, 0],
                 centers[ii, 1] - centers[jj, 1])
    m = len(ii)
    A = np.zeros((m + n, n))
    A[np.arange(m), ii] = 1.0
    A[np.arange(m), jj] = 1.0
    b = np.empty(m + n)
    b[:m] = d
    b[m:] = np.minimum(np.minimum(centers[:, 0], centers[:, 1]),
                       np.minimum(1.0 - centers[:, 0], 1.0 - centers[:, 1]))
    A[m:, np.arange(n)] = 1.0
    res = linprog(-np.ones(n), A_ub=A, b_ub=b,
                  bounds=[(0, None)] * n, method='highs')
    if res.success:
        return np.maximum(res.x, 0.0)
    return _fallback_radii(centers)


def _fallback_radii(centers):
    n = len(centers)
